<main id="main-content" class="singular-main page-main wrap" tabindex="-1" data-modal-inert><?php if (function_exists('shiki_breadcrumbs')) { shiki_breadcrumbs(); } ?><?php while (have_posts()) { the_post(); ?><article id="post-<?php the_ID(); ?>" <?php post_class('reading-article'); ?>><header class="article-header"><p class="eyebrow">INFORMATION</p><h1><?php echo esc_html(get_the_title() ?: '無題のページ'); ?></h1><?php if (get_the_modified_time('U') > get_the_time('U')) { ?><p class="article-meta">更新 <time datetime="<?php echo esc_attr(get_the_modified_date('c')); ?>"><?php echo esc_html(get_the_modified_date('Y.m.d')); ?></time></p><?php } ?></header><div class="entry-content"><?php the_content(); wp_link_pages(['before' => '<nav class="page-links-nav" aria-label="固定ページのページ分割">ページ: ', 'after' => '</nav>']); ?></div></article><?php if (comments_open() || get_comments_number()) { comments_template(); } } ?></main>
